import{_ as a,o as e,c as l,a2 as o}from"./chunks/framework.DSoq407f.js";const p=JSON.parse('{"title":"机器人管理","description":"","frontmatter":{},"headers":[],"relativePath":"console/bots.md","filePath":"console/bots.md","lastUpdated":1786505997000}'),r={name:"console/bots.md"};function i(s,t,d,n,h,c){return e(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="机器人管理" tabindex="-1">机器人管理 <a class="header-anchor" href="#机器人管理" aria-label="Permalink to &quot;机器人管理&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：怎么创建机器人、填凭证、装插件、配置、监控。</p></blockquote><h2 id="创建机器人" tabindex="-1">创建机器人 <a class="header-anchor" href="#创建机器人" aria-label="Permalink to &quot;创建机器人&quot;">​</a></h2><ol><li>进入机器人管理，点「创建机器人」。</li><li><strong>选择平台</strong>：从<a href="./../platforms/supported">支持的平台</a>里选一个（QQ 官方、Telegram 等）。</li><li><strong>填写凭证</strong>：按平台要求填应用 ID、Token、Secret 等。</li><li><strong>配置连接</strong>： <ul><li>Webhook 类：把生成的回调地址填到平台后台。</li><li>WebSocket / 轮询类：确认连接信息无误。</li></ul></li><li><strong>命名保存</strong>。</li></ol><div class="warning custom-block"><p class="custom-block-title">配额限制</p><p>可创建的机器人数量由你的<a href="./subscriptions">订阅套餐</a>决定。配额用完需升级套餐或删除旧机器人。</p></div><h2 id="机器人列表" tabindex="-1">机器人列表 <a class="header-anchor" href="#机器人列表" aria-label="Permalink to &quot;机器人列表&quot;">​</a></h2><p>每条机器人显示：</p><ul><li>名称、平台、状态（运行中 / 已停用 / 异常）</li><li>绑定的插件数量</li><li>创建时间</li></ul><p>支持启停、编辑、删除。</p><h2 id="配置机器人" tabindex="-1">配置机器人 <a class="header-anchor" href="#配置机器人" aria-label="Permalink to &quot;配置机器人&quot;">​</a></h2><p>点进某个机器人，可以配置：</p><h3 id="适配器设置" tabindex="-1">适配器设置 <a class="header-anchor" href="#适配器设置" aria-label="Permalink to &quot;适配器设置&quot;">​</a></h3><p>每个平台的机器人有一组<strong>适配器行为设置</strong>，例如 QQ 官方：</p><table tabindex="0"><thead><tr><th>设置</th><th>作用</th></tr></thead><tbody><tr><td>全量消息当作普通群消息</td><td>群里非 @消息也当作普通消息处理</td></tr><tr><td>忽略其他机器人发的消息</td><td>过滤掉其他 bot 的消息</td></tr><tr><td>忽略只 @其他机器人的消息</td><td>减少无关处理</td></tr><tr><td>忽略 @全体成员的消息</td><td>不响应 @全体</td></tr><tr><td>事件去重</td><td>防止重复处理</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">全量消息</p><p>开启「全量消息当作普通群消息」后，你的机器人能收到群里所有消息（不只 @它的），更多插件会触发。按需开启。</p></div><h3 id="已安装插件" tabindex="-1">已安装插件 <a class="header-anchor" href="#已安装插件" aria-label="Permalink to &quot;已安装插件&quot;">​</a></h3><p>查看这个机器人装了哪些插件，每个插件可：</p><ul><li>启用 / 停用</li><li>配置参数（来自插件的 <code>setting.json</code>）</li><li>设置优先级、拦截器开关</li><li>卸载</li></ul><h3 id="插件-webui" tabindex="-1">插件 WebUI <a class="header-anchor" href="#插件-webui" aria-label="Permalink to &quot;插件 WebUI&quot;">​</a></h3><p>装了 WebUI 的插件，在机器人配置页内嵌展示管理界面（如签到排行、商城订单）。</p><h2 id="监控" tabindex="-1">监控 <a class="header-anchor" href="#监控" aria-label="Permalink to &quot;监控&quot;">​</a></h2><p>查看机器人运行状态、最近事件、插件执行情况。异常会在列表标红。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>给机器人装功能 → <a href="./plugins">插件中心</a></li><li>配额不够 → <a href="./subscriptions">我的订阅</a></li></ul>',24)])])}const u=a(r,[["render",i]]);export{p as __pageData,u as default};
